// Raw tokens are only known for shares created in this page session;
// the management list itself never contains tokens.
const sessionTokens = new Map();

const STATUS_LABELS = {
  active: { label: '有效', className: 'status-active' },
  expired: { label: '已过期', className: 'status-expired' },
  revoked: { label: '已撤销', className: 'status-revoked' },
};
let serverShares = [];

function shareStatus(share) {
  return STATUS_LABELS[share.status] || STATUS_LABELS.active;
}

function shareUrl(token) {
  return `${location.origin}/api/shares/${token}/releases`;
}

function describeShareScope(share) {
  const parts = [];
  parts.push(share.request_id ? `request_id=${share.request_id}` : '全部请求');
  parts.push(share.from ? `from ${new Date(share.from).toLocaleString()}` : '不限起点');
  parts.push(share.to ? `to ${new Date(share.to).toLocaleString()}` : '不限终点');
  parts.push(`limit ${share.limit}`);
  return parts.join(' · ');
}

async function copyShareLink(token, button) {
  const url = shareUrl(token);
  try {
    await navigator.clipboard.writeText(url);
    button.textContent = '已复制';
  } catch (_) {
    const input = document.querySelector(`input[data-share-token="${token}"]`);
    if (input) {
      input.focus();
      input.select();
      document.execCommand('copy');
      button.textContent = '已复制';
    }
  }
  setTimeout(() => { button.textContent = '复制链接'; }, 2000);
}

async function revokeShare(shareId) {
  const message = document.getElementById('share-message');
  try {
    const response = await fetch(`/api/shares/id/${encodeURIComponent(shareId)}`, {
      method: 'DELETE',
    });
    if (!response.ok && response.status !== 204) {
      const data = await response.json().catch(() => null);
      message.className = 'error';
      message.textContent = `撤销失败：${formatError(data, response.status)}`;
      return;
    }
    message.className = 'success';
    message.textContent = '分享已撤销，链接立即失效。';
    await loadShares();
  } catch (error) {
    message.className = 'error';
    message.textContent = `撤销失败：${error.message}`;
  }
}

function renderShares() {
  const container = document.getElementById('shares');
  container.textContent = '';
  if (!serverShares.length) {
    const empty = document.createElement('p');
    empty.className = 'empty';
    empty.textContent = '暂无分享记录。';
    container.append(empty);
    return;
  }
  for (const share of serverShares) {
    const status = shareStatus(share);
    const card = document.createElement('article');
    card.className = 'release-card';
    const title = document.createElement('h3');
    const badge = document.createElement('span');
    badge.className = `status-badge ${status.className}`;
    badge.textContent = status.label;
    title.append('分享链接 ', badge);
    const details = document.createElement('dl');
    const items = [
      ['范围', describeShareScope(share)],
      ['过期时间', new Date(share.expires_at).toLocaleString()],
      ['创建时间', new Date(share.created_at).toLocaleString()],
      ['share_id', share.share_id],
    ];
    if (share.revoked_at) {
      items.push(['撤销时间', new Date(share.revoked_at).toLocaleString()]);
    }
    for (const [label, value] of items) {
      const dt = document.createElement('dt');
      dt.textContent = label;
      const dd = document.createElement('dd');
      dd.textContent = value;
      details.append(dt, dd);
    }
    card.append(title, details);
    const token = sessionTokens.get(share.share_id);
    const actions = document.createElement('div');
    actions.className = 'share-actions';
    if (token && share.status !== 'revoked') {
      const linkInput = document.createElement('input');
      linkInput.readOnly = true;
      linkInput.value = shareUrl(token);
      linkInput.setAttribute('data-share-token', token);
      linkInput.addEventListener('focus', () => linkInput.select());
      const copyButton = document.createElement('button');
      copyButton.type = 'button';
      copyButton.className = 'secondary';
      copyButton.textContent = '复制链接';
      copyButton.addEventListener('click', () => copyShareLink(token, copyButton));
      actions.append(linkInput, copyButton);
    }
    const revokeButton = document.createElement('button');
    revokeButton.type = 'button';
    revokeButton.className = 'danger';
    revokeButton.textContent = '按 share_id 撤销';
    revokeButton.disabled = share.status === 'revoked';
    revokeButton.addEventListener('click', () => revokeShare(share.share_id));
    actions.append(revokeButton);
    card.append(actions);
    container.append(card);
  }
}

async function loadShares() {
  const message = document.getElementById('shares');
  const filter = document.getElementById('share-status-filter').value;
  const params = new URLSearchParams({ limit: '100' });
  if (filter) params.set('status', filter);
  try {
    const response = await fetch(`/api/shares?${params.toString()}`);
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    serverShares = await response.json();
    renderShares();
  } catch (error) {
    message.textContent = `分享列表暂时不可用：${error.message}`;
  }
}

